sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float mode;
uniform float angle;
uniform float2 center;
uniform float falloff;
uniform float boost;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float3 sat3(float3 c, float s) {
    return mix(float3(dot(c, float3(0.2126, 0.7152, 0.0722))), c, s);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float2 d = coord - ctr;
    float fr = length(d) / (length(size) * 0.5);
    float2 dir = mode < 0.5 ? d / max(length(d), 0.001) * pow(fr, falloff) : float2(cos(radians(angle)), sin(radians(angle)));
    float3 acc = float3(0.0);
    float3 wsum = float3(0.0);
    for (int i = 0; i < 7; i++) {
        float t = float(i) / 6.0;
        float3 w = float3(saturate(1.0 - 2.0 * t), 1.0 - abs(2.0 * t - 1.0), saturate(2.0 * t - 1.0));
        acc += tex(coord + dir * (t - 0.5) * 2.0 * amount).rgb * w;
        wsum += w;
    }
    float3 o = acc / wsum;
    o = sat3(o, 1.0 + boost);
    return fin(c, float4(o, c.a), opacity);
}
